'use strict';
const D=window.NASRAL_DATA;
const $=s=>document.querySelector(s);
const fmt=(v,d=0)=>v===null||v===undefined?'—':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:d,minimumFractionDigits:d}).format(v);
const money=v=>`${fmt(v)} ₽`;
const duration=m=>`${Math.floor(m/60)} ч ${String(m%60).padStart(2,'0')} мин`;
const hours=m=>`${fmt(m/60,1)} ч`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const P=id=>D.players.find(p=>p.id===id)||D.history.find(p=>p.id===id);
const G=id=>D.games[id];
const A=id=>D.attempts.find(a=>a.id===id);
const L=id=>D.auctions.find(l=>l.id===id);
const active=D.players.filter(p=>p.points!==undefined);
const completion=p=>100*p.finished/(p.finished+p.dropped);
const efficiency=p=>p.points/(p.minutes/60);
const sum=(arr,key)=>arr.reduce((s,x)=>s+(x[key]||0),0);
const metrics={points:sum(active,'points'),minutes:sum(active,'minutes'),finished:sum(active,'finished'),dropped:sum(active,'dropped'),attempts:D.attempts.length,playing:D.attempts.filter(a=>a.status==='playing').length,waiting:D.auctions.filter(l=>l.status==='waiting').length,total:sum(D.auctions,'total'),winning:sum(D.auctions,'winning'),lots:D.auctions.length};
const paths={star:'m12 3 2.7 5.6 6.2.9-4.5 4.4 1.1 6.2L12 17.2l-5.5 2.9 1.1-6.2-4.5-4.4 6.2-.9Z',shield:'M12 3 4 6v6c0 4 8 9 8 9s8-5 8-9V6Z M8 12l3 3 5-6',risk:'M12 3 2 21h20L12 3Z M12 9v5 M12 17v1',trophy:'M7 3h10v7a5 5 0 0 1-10 0V3Z M7 5H3v3c0 3 2 4 4 4 M17 5h4v3c0 3-2 4-4 4 M12 15v6 M8 21h8',medal:'M8 3h8l-1 8H9L8 3Z M12 12a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',history:'M5 4v16 M5 5h15 M5 12h10 M5 19h12 M3 5h4 M3 12h4 M3 19h4',game:'M7 7h10c4 0 5 4 5 9 0 3-3 3-5-1H7c-2 4-5 4-5 1 0-5 1-9 5-9Z M7 9v5 M4.5 11.5h5 M16 10h.1 M19 13h.1',coins:'M3 6c0-2 18-2 18 0s-18 2-18 0Z M3 6v5c0 2 18 2 18 0V6 M3 11v5c0 2 18 2 18 0v-5 M3 16v4c0 2 18 2 18 0v-4',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z M12 6v6l4 2',arrow:'M4 12h15 M13 6l6 6-6 6',back:'M20 12H5 M11 6l-6 6 6 6',check:'m5 12 4 4L20 5',close:'m6 6 12 12 M6 18 18 6',plus:'M12 4v16 M4 12h16',chart:'M4 20V10h4v10 M10 20V4h4v16 M16 20V8h4v12',scales:'M12 3v18 M5 21h14 M4 6h16 M5 6 2 14h6L5 6Z M19 6l-3 8h6l-3-8Z',play:'m8 4 12 8-12 8V4Z',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z M12 10v7 M12 7v.2',sun:'M12 5a7 7 0 1 0 0 14 7 7 0 0 0 0-14Z M12 1v2 M12 21v2 M1 12h2 M21 12h2 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',bolt:'m13 2-9 12h7l-1 8L21 9h-8l1-7Z',snow:'M12 2v20 M3 7l18 10 M3 17 21 7 M9 4l3 3 3-3 M9 20l3-3 3 3',people:'M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Z M2 21v-3c0-5 12-5 12 0v3 M17 5a3 3 0 0 1 0 6 M18 14c4 0 4 4 4 7',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3V4Z M12 6v15'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`;
Object.assign(paths,{atom:'M12 3c-5 0-5 18 0 18s5-18 0-18Z M4 7c-2 4 13 13 16 9S7 3 4 7Z M4 17c3 4 18-5 16-9S2 13 4 17Z M12 12h.1',palm:'M12 22V9 M12 10C5 2 2 6 2 9c5-2 7 0 10 1Z M12 10c4-10 10-7 10-3-5-1-7 1-10 3Z M12 9c-1-9-7-9-8-5 M12 9c5-7 8-4 9-2 M6 22h12',wolf:'M3 3l6 4h6l6-4-2 12-7 7-7-7-2-12Z M5 8l5 4-3 3 M19 8l-5 4 3 3 M10 17l2 2 2-2 M12 12v5',double:'M3 6l4 4 5-7 5 7 4-4-2 11H5L3 6Z M6 21h12 M9 10v4 M15 10v4',laurel:'M8 21C1 17 1 8 7 3 M5 16l-3-2 M4 11l-2-2 M5 7 4 4 M16 21c7-4 7-13 1-18 M19 16l3-2 M20 11l2-2 M19 7l1-3 M9 16V8h6v8 M8 19h8',hourglass:'M5 3h14 M5 21h14 M7 3v5l10 8v5 M17 3v5L7 16v5 M9 6h6 M9 18h6'});
const badge=(name,color,title,extra='')=>`<button class="badge ${color||''} award-tooltip" data-award="${esc(title)}" data-award-kind="historical" ${extra} aria-label="${esc(title)}" title="${esc(title)}">${icon(name)}</button>`;
const rarityNames={signature:'Особая регалия',rare:'Редкая',standard:'Коллекционная'};
const rarityRank={signature:0,rare:1,standard:2};
const categoryOrder=['Титулы','Призовые места','Рекорды','Роли','Карьера','Сезоны'];
const awardsFor=p=>D.achievements.filter(a=>a.player===p.id).sort((a,b)=>rarityRank[a.rarity]-rarityRank[b.rarity]||categoryOrder.indexOf(a.category)-categoryOrder.indexOf(b.category));
function awardArt(a){
 const frame=a.rarity==='signature'?'<path d="M20 20 28 6l12 10L50 4l10 12L72 6l8 14 8 20-5 34-33 22-33-22-5-34Z"/><path d="m24 34 26-14 26 14v35L50 86 24 69Z"/>':a.rarity==='rare'?'<path d="M50 5 84 24v49L50 95 16 73V24Z"/><path d="m50 13 27 16v39L50 86 23 68V29Z"/>':'<circle cx="50" cy="48" r="38"/><path d="m29 80-3 15 24-9 24 9-3-15"/><circle cx="50" cy="48" r="31"/>';
 return `<svg class="award-art ${a.rarity} ${esc(a.color)}" viewBox="0 0 100 100" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true">${frame}<svg x="29" y="25" width="42" height="42" viewBox="0 0 24 24" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[a.symbol]||paths.trophy}"/></svg><path d="m43 76 7-4 7 4-7 4Z" fill="currentColor" stroke="none"/></svg>`;
}
const achievementBadge=a=>`<button class="badge achievement-badge ${a.rarity} ${esc(a.color)}" data-achievement="${a.id}" aria-label="${esc(a.title)}" title="${esc(a.title)}">${awardArt(a)}</button>`;
const eventByName=name=>Object.entries(D.events).find(([id,e])=>e.name===name);
const chip=(season,rank)=>{const [id,e]=eventByName(season)||[];return e?`<a class="season-chip ${id}" href="?page=${e.route}" title="Открыть ${season}">${icon(e.symbol)}${season}${rank?` · #${rank}`:''}</a>`:'';};
const seasons=p=>[p.rank25?chip('NASRAL 2025',p.rank25):'',p.rank26?chip('NASSAL 2026',p.rank26):'',p.points!==undefined&&!['candidates','voting','selection'].includes(page)?chip('NASRAL 2026'):''].join('');
const regalia=p=>awardsFor(p).filter(a=>a.category!=='Сезоны'&&(!['candidates','voting','selection'].includes(page)||!a.events.includes('nasral-2026'))).slice(0,2).map(achievementBadge).join('');
const portrait=p=>`../assets/portraits/${p.portraitFile||((p.asset||p.name)+'.jpg')}`;
const clearPortrait=p=>!!p.portraitFile;
const initials=p=>p.name.replace(/[^a-zA-Zа-яА-Я]/g,'').slice(0,2).toUpperCase();
const imagePortrait=(p,cls='')=>clearPortrait(p)?`<img class="${cls}" src="${portrait(p)}" alt="${esc(p.name)}">`:`<span class="${cls} portrait-monogram" role="img" aria-label="${esc(p.name)} — монограмма">${initials(p)}</span>`;
const avatar=(p,cls='')=>imagePortrait(p,'avatar '+cls);
const player=(p,sub='',mini=false)=>`<div class="player"><a href="?page=profile&player=${p.id}">${avatar(p)}</a><div><a href="?page=profile&player=${p.id}"><strong>${esc(p.name)}</strong></a>${sub?`<div class="meta">${sub}</div>`:''}</div></div>`;
const cover=(game,cls='game-mini')=>`<img class="${cls}" src="${G(game).cover}" alt="Обложка ${esc(G(game).title)}">`;
const gameLink=a=>`<a class="game-title" href="?page=lot&lot=${a.lot||a.id}">${cover(a.game)}<span>${esc(G(a.game).title)}</span></a>`;
const outcomeNames={finished:'Пройдено',playing:'В игре',dropped:'Дроп игры',waiting:'Ожидает старта'};
const status=s=>`<span class="game-status ${s}"><i class="outcome-dot"></i>${outcomeNames[s]}</span>`;
const btn=(page,label,cls='quiet')=>`<a class="btn ${cls}" href="?page=${page}">${label}</a>`;
const pill=(text,color='')=>`<span class="pill ${color}">${text}</span>`;
let params=new URLSearchParams(location.search);
let page=params.get('page')||'candidates';
let selected=[];
try{selected=JSON.parse(sessionStorage.getItem('nasral-selection')||'[]').filter(id=>D.players.some(p=>p.id===id));}catch{}
if(page==='selection'&&!selected.length&&params.get('example')==='full')selected=[...D.selection];
let favorite=sessionStorage.getItem('nasral-favorite');if(!selected.includes(favorite))favorite=selected.includes('mel')?'mel':selected[0]||null;
let state={candidateOffset:0,search:'',platform:'all',statsSort:'points',statsDirection:-1,statsTab:'general',gameStatus:'all',gamePlayer:'all',auctionTab:params.get('auctionTab')||'top',auctionFilter:'all',donutMode:'genre',donutUnit:'money',voteTab:'rating',profileTab:params.get('tab')||'awards',awardCategory:'all',awardOffset:0,eventSeason:'all',eventKind:'all',eventGame:'all',eventMedia:'all',eventOffset:0,compareLeft:params.get('left')||'flash',compareRight:params.get('right')||'mel',gameOffset:5*Math.max(0,Number(params.get('gamePage'))||0),auctionOffset:5*Math.max(0,Number(params.get('auctionPage'))||0),...history.state?.view};
const saveSelection=()=>{sessionStorage.setItem('nasral-selection',JSON.stringify(selected));sessionStorage.setItem('nasral-favorite',favorite||'');};
function pager(kind,offset,total,size=5){return `<div class="list-pager"><span>Показано ${total?offset+1:0}–${Math.min(offset+size,total)} из ${total}</span><div class="row"><button class="btn small quiet" data-list="${kind}" data-offset="${offset-size}" ${offset===0?'disabled':''}>Назад</button><button class="btn small quiet" data-list="${kind}" data-offset="${offset+size}" ${offset+size>=total?'disabled':''}>Дальше</button></div></div>`;}
function head(title,sub,eye,right=''){return `<div class="page-head"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><div class="subtitle">${sub}</div></div><div class="head-tools">${right}</div></div>`;}
function header(){let section=['candidates','voting','selection'].includes(page)?'vote':['standings','statistics','comparison'].includes(page)?'tournament':page==='games'?'games':['auctions','lot'].includes(page)?'auctions':'history';return `<header class="topbar"><a class="brand" href="?page=standings" aria-label="NASRAL — турнир"><svg class="brand-mark" viewBox="0 0 44 50" fill="none"><path d="m7 39 10-28M17 41l10-30M27 39l10-28" stroke="currentColor" stroke-width="3"/><path d="m7 46 15-3 15 3M7 5l15 3 15-3" stroke="currentColor"/></svg><div><div class="brand-title">NASRAL</div><div class="brand-sub">ИГРЫ · ИСТОРИЯ · 2026</div></div></a><nav class="nav" aria-label="Главные разделы">${[['vote','candidates','Голосование'],['tournament','standings','Турнир'],['games','games','Игры'],['auctions','auctions','Аукционы'],['history','hall','История']].map(([id,p,n])=>`<a class="${section===id?'active':''}" href="?page=${p}" ${section===id?'aria-current="page"':''}>${n}</a>`).join('')}</nav><div class="top-end"><span class="top-season">Сезон III · NASRAL 2026</span><span class="top-separator"></span><span>${section==='vote'?'Выбор состава':page==='season'?'Архив сезона':'День 07 / 14'}</span></div></header>`;}
function footer(){return `<footer class="footer"><span>NASRAL <span class="dot">◆</span> NASSAL</span><span>УЧАСТНИКИ · ИГРЫ · ДОСТИЖЕНИЯ · ИСТОРИЯ</span><span>${['candidates','voting','selection'].includes(page)?'ОТБОР УЧАСТНИКОВ':page==='season'?'АРХИВ · ИТОГОВЫЕ РЕЗУЛЬТАТЫ':'СРЕЗ · ДЕНЬ 07 · 21:45'}</span></footer>`;}
function kpi(label,value,sub,ico='chart'){return `<div class="panel kpi"><div class="spread"><span class="kpi-label">${label}</span>${icon(ico)}</div><div class="big-number">${value}</div><div class="kpi-sub">${sub}</div></div>`;}
function candidateCard(p){return `<article class="candidate ${selected.includes(p.id)?'selected':''}"><a class="candidate-picture" href="?page=profile&player=${p.id}" aria-label="Профиль ${esc(p.name)}">${imagePortrait(p)}</a><div class="candidate-info"><a href="?page=profile&player=${p.id}" class="candidate-name ${p.name.length>15?'long':''}">${esc(p.name)}</a><div class="spread"><span class="platform ${p.platform==='Kick'?'kick':''}">${p.platform}</span><div class="badges">${regalia(p)}</div></div><div class="candidate-seasons">${seasons(p)||'<span class="tiny muted">Без прошлых сезонов</span>'}</div><div class="candidate-bottom"><a class="tiny muted" href="?page=profile&player=${p.id}">Профиль ${icon('arrow','sm')}</a><button class="btn small ${selected.includes(p.id)?'selected':'quiet'}" data-select="${p.id}">${icon(selected.includes(p.id)?'check':'plus','sm')}${selected.includes(p.id)?'В составе':'Выбрать'}</button></div></div></article>`;}
function legend(){const ids=['series-double-flash','nasral-2025-flash-place','nassal-2026-dunduk-place','mge-2024-mel-judge'];return `<aside class="panel panel-inner collection-legend"><div class="eyebrow">История в значках</div><h2>Коллекция достижений</h2><div class="section-rule"></div>${ids.map(id=>{const a=D.achievements.find(a=>a.id===id);return `<div class="legend-item">${achievementBadge(a)}<div class="copy"><strong>${a.title}</strong><p>${rarityNames[a.rarity]}</p></div></div>`;}).join('')}<div class="section-rule"></div><div class="section-label">Эмблемы сезонов</div><div class="legend-item">${chip('NASRAL 2025')}</div><div class="legend-item">${chip('NASSAL 2026')}</div><div class="section-rule"></div><p class="legend-note">За каждым знаком — результат, роль или сезон. Нажмите, чтобы узнать условие получения и открыть историю.</p><p class="small muted" style="line-height:1.65;margin-top:20px">Редкость различается формой и подписью. Награды не добавляют очков и голосов.</p></aside>`;}

function candidates(){let list=D.players.filter(p=>(state.platform==='all'||p.platform===state.platform)&&p.name.toLowerCase().includes(state.search.toLowerCase()));let visible=list.slice(state.candidateOffset,state.candidateOffset+10);return head('Кандидаты NASRAL 2026','История участников, регалии и выбор состава','Голосование / Кандидаты',btn('voting','Рейтинг голосования '+icon('arrow'),'quiet'))+`<div class="columns"><section><div class="toolbar"><input class="input" id="candidate-search" data-search placeholder="Найти участника" value="${esc(state.search)}" aria-label="Поиск кандидата"><select class="select" id="platform-select" aria-label="Платформа"><option value="all">Все платформы</option><option ${state.platform==='Twitch'?'selected':''}>Twitch</option><option ${state.platform==='Kick'?'selected':''}>Kick</option></select><span class="toolbar-end">${list.length} кандидатов · фаворит + ещё 8</span></div><div class="candidate-grid">${visible.map(candidateCard).join('')||'<div class="empty-state full-width">Ничего не найдено. Измените поиск или платформу.</div>'}</div><div class="pager"><span>Показано ${list.length?state.candidateOffset+1:0}–${Math.min(state.candidateOffset+10,list.length)} из ${list.length}</span><button class="btn small quiet" data-candidate-page="0" ${state.candidateOffset===0?'disabled':''}>${icon('back','sm')}</button><button class="btn small quiet" data-candidate-page="10" ${list.length<=10||state.candidateOffset===10?'disabled':''}>${icon('arrow','sm')}</button></div><div class="selection-strip"><div><strong>Мой состав <span class="gold">${selected.length} / 9</span></strong><p>Один фаворит и восемь дополнительных участников</p></div>${btn('selection','Проверить выбор '+icon('arrow'),'primary')}</div></section>${legend()}</div>`;}
function voting(){let list=[...D.players];if(state.voteTab==='favorites')list.sort((a,b)=>b.favorites-a.favorites);return head('Рейтинг голосования','Места в отборе, голоса и выборы фаворитом — отдельные показатели','Голосование / Рейтинг',pill('<i class="live-dot"></i>Голосование открыто','green'))+`<div class="columns"><section class="panel"><div class="panel-heading"><div class="tabs" style="margin:0;border:0">${[['rating','Общий рейтинг'],['favorites','Фавориты']].map(([id,n])=>`<button data-vote-tab="${id}" class="${state.voteTab===id?'active':''}">${n}</button>`).join('')}</div><span class="small muted">Рейтинг, % · показатель отбора</span></div><table class="rating-table"><thead><tr><th>#</th><th>Кандидат</th><th>Регалии</th><th class="right">Голоса</th><th class="right">Фавориты</th><th>Рейтинг, %</th><th>Статус отбора</th></tr></thead><tbody>${list.map((p,i)=>`${state.voteTab==='rating'&&i===9?'<tr class="cut-label"><td colspan="7">ПРОХОДНОЙ ПОРОГ · ПЕРВЫЕ 9 МЕСТ ПО РЕГЛАМЕНТУ</td></tr>':''}<tr><td class="rank-cell">${state.voteTab==='rating'?p.voteRank:i+1}</td><td>${player(p,`<span class="platform ${p.platform==='Kick'?'kick':''}">${p.platform}</span>`)}</td><td><div class="row">${regalia(p)}</div></td><td class="right number">${fmt(p.votes)}</td><td class="right number">${fmt(p.favorites)}</td><td><div class="row"><div class="rating-bar"><i style="width:${p.rating/5.8*100}%"></i></div><b class="number">${fmt(p.rating,1)}</b></div></td><td>${pill(p.voteRank<=9?'В зоне прохода':'Ниже порога',p.voteRank<=9?'green':'')}</td></tr>`).join('')}</tbody></table></section><aside class="stack"><section class="panel panel-inner"><div class="eyebrow">Выбор состава</div><h2>Как проходит отбор</h2>${[['1','Выберите одного фаворита и ещё восемь кандидатов.'],['2','Рейтинг определяет проходной состав. До закрытия результат предварительный.'],['3','Исторические награды помогают узнать участника, но не влияют на рейтинг.']].map(([n,t])=>`<div class="rule-line"><span class="rule-number">${n}</span><span>${t}</span></div>`).join('')}${btn('candidates','Выбрать участников '+icon('arrow'),'primary full')}</section><section class="panel panel-inner"><h3>Сводка голосования</h3><dl class="stat-list"><div><dt>Кандидатов</dt><dd>12</dd></div><div><dt>Проходят в состав</dt><dd>9</dd></div><div><dt>Выборов в состав</dt><dd>${fmt(sum(D.players,'votes'))}</dd></div><div><dt>Лидер рейтинга</dt><dd style="font-size:18px">F1ashko</dd></div></dl><p class="legend-note" style="margin-top:22px">Равные округлённые проценты не означают одинаковое место. Используется порядок рейтинга.</p></section></aside></div>`;}
function nearestAttemptLot(playerId,day){return D.attempts.filter(a=>a.player===playerId&&a.status==='finished'&&a.day<=day).sort((a,b)=>b.day-a.day)[0]?.lot||null;}
function chart(players=active.slice(0,5),height=270){const w=490,h=height,left=40,right=20,top=22,bottom=38,max=1400;const colors=['#d5b57b','#8bb9e7','#b5a0d9','#83d0ad','#e29c85'];let traces=players.map(p=>Array.from({length:7},(_,i)=>sum(D.attempts.filter(a=>a.player===p.id&&a.day<=i+1&&a.status==='finished'),'points')));return `<svg class="chart" style="height:${height}px" viewBox="0 0 ${w} ${h}" role="img" aria-label="Накопление GGP по дням с первого по седьмой">${[0,350,700,1050,1400].map(v=>`<path d="M${left} ${h-bottom-v/max*(h-top-bottom)}H${w-right}" stroke="#2b3b4b"/><text x="${left-8}" y="${h-bottom-v/max*(h-top-bottom)+4}" text-anchor="end">${fmt(v)}</text>`).join('')}${Array.from({length:7},(_,i)=>`<text x="${left+i*(w-left-right)/6}" y="${h-13}" text-anchor="middle">Д${i+1}</text>`).join('')}${traces.map((vs,pi)=>`<path d="${vs.map((v,i)=>`${i===0?'M':'L'}${left+i*(w-left-right)/6},${h-bottom-v/max*(h-top-bottom)}`).join(' ')}" fill="none" stroke="${colors[pi]}" stroke-width="2.6"/>${vs.map((v,i)=>`<a href="?page=lot&lot=${nearestAttemptLot(players[pi].id,i+1)}"><circle cx="${left+i*(w-left-right)/6}" cy="${h-bottom-v/max*(h-top-bottom)}" r="4" fill="${colors[pi]}"><title>${players[pi].name} · День ${i+1} · ${fmt(v)} GGP</title></circle></a>`).join('')}`).join('')}</svg><div class="chart-legend">${players.map((p,i)=>`<span><i style="background:${colors[i]}"></i>${p.name}</span>`).join('')}</div>`;}
function recentEvents(limit=3){return [...D.attempts].filter(a=>a.status==='finished').sort((a,b)=>b.day-a.day).slice(0,limit).map(a=>`<a class="event-row" href="?page=lot&lot=${a.lot}"><div><b>${P(a.player).name}</b><small>${G(a.game).title} · День ${a.day}</small></div><strong class="positive number">+${fmt(a.points)} GGP</strong></a>`).join('');}
function standings(){return head('Турнирная таблица','Место в гонке, текущая игра и история начислений','Турнир / Гонка по очкам',pill('<i class="live-dot"></i>День 07 / 14','green'))+`<div class="kpis">${kpi('Лидер турнира','F1ashko',`${fmt(active[0].points)} GGP`,'trophy')}${kpi('Завершено прохождений',fmt(metrics.finished),`Из ${metrics.attempts} начатых попыток`,'game')}${kpi('Игровое время',hours(metrics.minutes),`Все ${active.length} участников`,'clock')}${kpi('До финиша сезона','7 дней','Прошло 7 из 14 дней','history')}</div><div class="columns wide-side"><section class="panel"><div class="panel-heading"><h2>Положение участников</h2>${btn('statistics','Расширенная статистика '+icon('arrow'),'small quiet')}</div><table class="standings-table"><thead><tr><th>#</th><th>Участник</th><th class="right">GGP</th><th class="right">До лидера</th><th>Δ места¹</th><th>Текущая игра</th></tr></thead><tbody>${active.map((p,i)=>`<tr><td class="rank-cell">${i+1}</td><td>${player(p,`${regalia(p)}${p.rank26?`NASSAL 2026 · #${p.rank26}`:p.rank25?`NASRAL 2025 · #${p.rank25}`:'Дебют в серии'}`)}</td><td class="right number score"><a href="?page=profile&player=${p.id}">${fmt(p.points)}</a></td><td class="right number muted">${i?`−${fmt(active[0].points-p.points)}`:'Лидер'}</td><td class="${p.delta>0?'positive':p.delta<0?'negative':'muted'}">${p.delta>0?'↑ +':p.delta<0?'↓ ':''}${p.delta||'—'}</td><td><a class="current-game" href="?page=lot&lot=${D.attempts.find(a=>a.player===p.id&&a.status==='playing').lot}">${cover(p.current)}<span>${G(p.current).title}</span></a></td></tr>`).join('')}</tbody></table><div class="chart-note">¹ Изменение места с начала шестого дня. Исторические медали не влияют на текущие очки.</div></section><aside class="stack"><section class="panel"><div class="panel-heading"><h2>Гонка GGP</h2><span class="small muted">Дни 1–7</span></div><div class="chart-wrap">${chart()}</div><div class="chart-note">Очки с начала турнира до текущего дня. Точка открывает связанное прохождение.</div></section><section class="panel panel-inner"><h3>Последние начисления</h3>${recentEvents(1)}</section></aside></div><div class="shortcuts">${[['hall','trophy','Чемпионы серии','Титулы, сезоны и исторические результаты'],['games','game','Игры участников','Текущие попытки, финиши и дропы'],['auctions','coins','Экономика аукционов','Варианты, ставки и последствия выбора']].map(([p,i,n,t])=>`<a class="panel shortcut" href="?page=${p}">${icon(i)}<div><strong>${n}</strong><small>${t}</small></div><span style="margin-left:auto">${icon('arrow')}</span></a>`).join('')}</div>`;}
function statistics(){let list=[...active].sort((a,b)=>state.statsDirection*((state.statsSort==='efficiency'?efficiency(a):state.statsSort==='completion'?completion(a):a[state.statsSort])-(state.statsSort==='efficiency'?efficiency(b):state.statsSort==='completion'?completion(b):b[state.statsSort])));let columns=[['points','GGP'],['finished','Финиши'],['dropped','Дропы'],['minutes','Часы'],['efficiency','GGP/ч'],['completion','% финиша']];return head('Статистика участников','Игры, время и эффективность за один и тот же период','Турнир / Статистика',btn('comparison','Сравнить участников '+icon('arrow'),'primary'))+`<div class="tabs">${[['general','Общая'],['finishes','Прохождения'],['efficiency','Эффективность']].map(([id,n])=>`<button data-stats-tab="${id}" class="${state.statsTab===id?'active':''}">${n}</button>`).join('')}<a href="?page=comparison">Сравнение</a><span style="margin-left:auto;align-self:center" class="small muted">NASRAL 2026 · День 07 · ${active.length} участников</span></div><div class="columns"><section class="stack">${state.statsTab==='finishes'?`<section class="panel"><div class="panel-heading"><h2>Последние завершённые попытки</h2>${btn('games&status=finished','Все прохождения '+icon('arrow'),'small quiet')}</div>${gameTable(D.attempts.filter(a=>a.status==='finished').sort((a,b)=>b.day-a.day||b.id.localeCompare(a.id)),5)}</section>`:`<div class="panel"><div class="panel-heading"><h2>${state.statsTab==='efficiency'?'Эффективность за сезон':state.statsTab==='finishes'?'Результаты прохождений':'Сводная статистика'}</h2><span class="small muted">Сортировка по заголовкам ↓↑</span></div><table class="statistics-table"><thead><tr><th>#</th><th>Участник</th><th class="right">Попытки</th>${columns.map(([id,n])=>`<th class="right"><button class="table-button" data-sort="${id}">${n}${state.statsSort===id?(state.statsDirection===-1?' ↓':' ↑'):''}</button></th>`).join('')}</tr></thead><tbody>${list.map((p,i)=>`<tr><td class="rank-cell">${i+1}</td><td>${player(p)}</td><td class="right number">${p.attempts}</td><td class="right number gold">${fmt(p.points)}</td><td class="right number"><a href="?page=games&player=${p.id}&status=finished">${p.finished}</a></td><td class="right number"><a href="?page=games&player=${p.id}&status=dropped">${p.dropped}</a></td><td class="right number">${fmt(p.minutes/60,1)}</td><td class="right number">${fmt(efficiency(p),1)}</td><td class="right number">${fmt(completion(p),1)}<div class="finish-bar"><i style="width:${completion(p)}%"></i></div></td></tr>`).join('')}</tbody></table><div class="chart-note">Финиш: завершённые / (завершённые + дропнутые). Текущие попытки в знаменатель не входят.</div></div>`}<section class="panel panel-inner"><div class="spread" style="margin-bottom:12px"><h3>${state.statsTab==='efficiency'?'Прозрачные показатели':'Прохождения Melharucos'}</h3><a href="?page=profile&player=mel" class="small gold">Профиль ${icon('arrow','sm')}</a></div>${state.statsTab==='efficiency'?'<div class="row" style="gap:35px"><div><strong class="gold">GGP / игровые часы</strong><p class="small muted">Очки и время одного среза</p></div><div><strong>Сравнение с HLTB — н/д</strong><p class="small muted">Нет проверенного ориентира для условий игры</p></div><div><strong>Без общего «рейтинга силы»</strong><p class="small muted">Деньги зрителей не измеряют мастерство</p></div></div>':library('mel',6)}</section></section><aside class="stack"><section class="panel"><div class="panel-heading"><h3>Сводка сезона</h3></div><div class="aside-kpis"><div><span class="small muted">Попыток</span><strong>${metrics.attempts}</strong></div><div><span class="small muted">Завершено</span><strong>${metrics.finished}</strong></div><div><span class="small muted">Часов</span><strong>${fmt(metrics.minutes/60)}</strong></div><div><span class="small muted">Суммарный GGP</span><strong style="font-size:26px">${fmt(metrics.points)}</strong></div></div></section><section class="panel panel-inner"><h3>Лидеры по метрикам</h3>${[['Лучший темп',[...active].sort((a,b)=>efficiency(b)-efficiency(a))[0],p=>`${fmt(efficiency(p),1)} GGP/ч`],['Больше финишей',[...active].sort((a,b)=>b.finished-a.finished)[0],p=>`${p.finished} игр`],['Больше часов',[...active].sort((a,b)=>b.minutes-a.minutes)[0],p=>hours(p.minutes)]].map(([n,p,v])=>`<div class="metric-leader"><div>${avatar(p)}</div><div><div class="tiny muted" style="margin-bottom:6px">${n}</div><a href="?page=profile&player=${p.id}"><b class="small">${p.name}</b></a></div><b class="leader-score">${v(p)}</b></div>`).join('')}</section></aside></div>`;}
function library(id,count=5){let items=D.attempts.filter(a=>a.player===id&&a.status==='finished').slice(0,count);return `<div class="mini-library">${items.map(a=>`<a class="mini-game" href="?page=lot&lot=${a.lot}">${cover(a.game,'')}<div class="title">${G(a.game).title}</div><div class="result">✓ ${fmt(a.points)} GGP</div><div class="tiny muted" style="margin-top:5px">${duration(a.minutes)}</div></a>`).join('')}</div>`;}
function gameTable(items,limit=5){return `<table class="games-table"><thead><tr><th>Игра / попытка</th><th>Участник</th><th>Статус</th><th class="right">Время</th><th class="right">GGP</th></tr></thead><tbody>${items.slice(0,limit).map(a=>`<tr><td>${gameLink(a)}</td><td>${player(P(a.player))}</td><td>${status(a.status)}</td><td class="right number">${duration(a.minutes)}</td><td class="right number ${a.points?'gold':''}">${a.points===null?'Не начислены':fmt(a.points)}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty-state">Прохождений с такими условиями нет.</div></td></tr>'}</tbody></table>`;}
function games(){let playerFilter=params.get('player')||state.gamePlayer;let statusFilter=params.get('status')||state.gameStatus;let items=D.attempts.filter(a=>(playerFilter==='all'||a.player===playerFilter)&&(statusFilter==='all'||a.status===statusFilter)&&G(a.game).title.toLowerCase().includes(state.search.toLowerCase()));if(state.gameOffset>=items.length)state.gameOffset=0;const focus=A(D.focusAttempt),focusLot=L(focus.lot);let playing=D.attempts.filter(a=>a.status==='playing').slice(0,3);return head('Игры и прохождения','Каждая попытка связана с участником, аукционом и результатом','Турнир / Игры',pill(`${metrics.playing} участников играют сейчас`,'blue'))+`<div class="columns"><section><div class="active-games">${playing.map(a=>`<a class="panel active-game" href="?page=lot&lot=${a.lot}">${cover(a.game,'active-cover')}<div class="game-info"><h3>${G(a.game).title}</h3><div class="spread"><div class="player">${avatar(P(a.player))}<strong class="small">${P(a.player).name}</strong></div>${status('playing')}</div><div class="elapsed"><span>${icon('clock','sm')} ${duration(a.minutes)}</span><span>Текущая попытка</span></div></div></a>`).join('')}</div><div class="toolbar"><input id="game-search" data-search class="input" placeholder="Найти игру" value="${esc(state.search)}" aria-label="Поиск игры"><select class="select" id="game-player" aria-label="Участник"><option value="all">Все участники</option>${active.map(p=>`<option value="${p.id}" ${playerFilter===p.id?'selected':''}>${p.name}</option>`).join('')}</select><select class="select" id="game-status" aria-label="Статус игры"><option value="all">Все статусы</option>${['playing','finished','dropped'].map(s=>`<option value="${s}" ${statusFilter===s?'selected':''}>${outcomeNames[s]}</option>`).join('')}</select><span class="toolbar-end">Найдено ${items.length} попыток</span></div><div class="panel"><div class="panel-heading"><h2>${statusFilter==='all'?'Последние игровые попытки':outcomeNames[statusFilter]}</h2><span class="small muted">Попытки ${items.length?state.gameOffset+1:0}–${Math.min(state.gameOffset+5,items.length)} из ${items.length}</span></div>${gameTable([...items].sort((a,b)=>b.day-a.day||b.id.localeCompare(a.id)).slice(state.gameOffset),5)}${pager('games',state.gameOffset,items.length)}<div class="chart-note">Каждая строка — отдельная попытка. Дроп игры не означает выход из турнира.</div></div></section><aside class="stack"><section class="panel"><div class="panel-heading"><h3>Игры сезона</h3></div><div class="aside-kpis"><div><span class="small muted">В игре</span><strong class="blue">${metrics.playing}</strong></div><div><span class="small muted">Пройдено</span><strong class="positive">${metrics.finished}</strong></div><div><span class="small muted">Дропы игр</span><strong class="negative">${metrics.dropped}</strong></div><div><span class="small muted">Ожидают старта</span><strong>${metrics.waiting}</strong></div></div><div class="chart-note">${metrics.attempts} начатых попыток + ${metrics.waiting} назначения в ожидании</div></section><section class="panel panel-inner"><h3>Последние результаты</h3>${recentEvents(4)}</section><section class="panel panel-inner"><div class="eyebrow">История одного назначения</div><h3>Inscryption → Melharucos</h3><p class="small muted" style="line-height:1.6">${money(focusLot.winning)} · ${duration(focus.minutes)} · +${focus.points} GGP. ${focusLot.condition}.</p>${btn('lot&lot='+A(D.focusAttempt).lot,'Открыть историю '+icon('arrow'),'full quiet')}</section></aside></div>`;}
const colors=['#d5b57b','#8bb9e7','#b5a0d9','#83d0ad','#df9b8f','#8ca5a7','#a5a1d6','#c9bd92'];
function donut(baseLots=D.auctions){if(!baseLots.length)return '<div class="empty-state">В этой подборке нет аукционов.</div>';let groups={};baseLots.forEach(l=>{let key=state.donutMode==='outcome'?outcomeNames[l.status]:l.genre;groups[key]=(groups[key]||0)+(state.donutUnit==='money'?l.total:1);});let values=Object.entries(groups).sort((a,b)=>b[1]-a[1]);let total=values.reduce((s,x)=>s+x[1],0),pos=0;let conic=values.map(([n,v],i)=>{let start=pos;pos+=v/total*100;return `${colors[i]} ${start}% ${pos}%`;}).join(',');return `<div class="toolbar" style="margin:0;gap:8px"><select id="donut-mode" class="select" style="width:100%" aria-label="Разрез распределения"><option value="genre" ${state.donutMode==='genre'?'selected':''}>Жанры игр</option><option value="outcome" ${state.donutMode==='outcome'?'selected':''}>По исходам игр</option></select><select id="donut-unit" class="select" style="width:100%" aria-label="Единица распределения"><option value="money" ${state.donutUnit==='money'?'selected':''}>Рубли</option><option value="lots" ${state.donutUnit==='lots'?'selected':''}>Лоты</option></select></div><div class="donut" style="background:conic-gradient(${conic})"><div class="donut-hole"><b>${state.donutUnit==='money'?fmt(total/1000000,2)+' млн':fmt(total)}</b><small>${state.donutUnit==='money'?'₽ · все варианты':'аукционных лотов'}</small></div></div>${values.map(([n,v],i)=>`<button class="donut-item full-width" data-auction-filter="${esc(n)}" style="background:none;text-align:left;padding-left:0;padding-right:0"><span><i class="dot" style="background:${colors[i]}"></i>${n}</span><span><strong>${fmt(v/total*100,1)}%</strong><small>${state.donutUnit==='money'?money(v):fmt(v)+' лотов'}</small></span></button>`).join('')}`;}
function auctions(){let playerFilter=params.get('player');let cohort=D.auctions.filter(l=>!playerFilter||l.player===playerFilter);let list=cohort.filter(l=>state.auctionFilter==='all'||l.genre===state.auctionFilter||outcomeNames[l.status]===state.auctionFilter).sort((a,b)=>b.winning-a.winning);let cohortTotal=sum(list,'total'),cohortWinning=sum(list,'winning'),record=list[0];let optionCount=list.reduce((n,l)=>n+l.options.filter(o=>!o.winner).length,0),pageCount=state.auctionTab==='unselected'?optionCount:list.length;if(state.auctionOffset>=pageCount)state.auctionOffset=0;let rows;if(state.auctionTab==='unselected'){const options=list.flatMap(l=>l.options.filter(o=>!o.winner).map(o=>({...o,lot:l}))).sort((a,b)=>b.amount-a.amount);rows=`<table class="auction-table unselected-table"><thead><tr><th>Не выбранный вариант</th><th>Участник</th><th class="right">Ставки на вариант</th><th>Что выбрали</th></tr></thead><tbody>${options.slice(state.auctionOffset,state.auctionOffset+5).map(o=>`<tr><td><a class="game-title" href="?page=lot&lot=${o.lot.id}">${cover(o.game,'')}<span><b>${G(o.game).title}</b><small>Не выбран в ${o.lot.id}</small></span></a></td><td>${player(P(o.lot.player))}</td><td class="right number gold">${money(o.amount)}<small class="muted">${fmt(o.amount/o.lot.total*100,1)}% объёма лота</small></td><td><a href="?page=lot&lot=${o.lot.id}">${G(o.lot.game).title}<small class="muted">${money(o.lot.winning)}</small></a></td></tr>`).join('')}</tbody></table>`;}else if(state.auctionTab==='players'){rows=`<table class="auction-table"><thead><tr><th>Участник</th><th class="right">Назначений</th><th class="right">Победившие варианты</th><th class="right">Средняя сумма</th><th>Исходы</th></tr></thead><tbody>${active.filter(p=>list.some(l=>l.player===p.id)).map(p=>{let lots=list.filter(l=>l.player===p.id);return `<tr><td>${player(p)}</td><td class="right">${lots.length}</td><td class="right number gold">${money(sum(lots,'winning'))}</td><td class="right number">${money(Math.round(sum(lots,'winning')/lots.length))}</td><td class="small">${lots.filter(l=>l.status==='finished').length} финишей / ${lots.filter(l=>l.status==='dropped').length} дропов</td></tr>`;}).join('')||'<tr><td colspan="5"><div class="empty-state">В этой подборке нет назначений.</div></td></tr>'}</tbody></table>`;}else{rows=`<table class="auction-table"><thead><tr><th>#</th><th>Игра / победивший вариант</th><th>Участник</th><th class="right">Победившая сумма</th><th>Итог игры</th></tr></thead><tbody>${list.slice(state.auctionOffset,state.auctionOffset+5).map((l,i)=>`<tr><td class="rank-cell">${state.auctionOffset+i+1}</td><td><a class="game-title" href="?page=lot&lot=${l.id}">${cover(l.game,'')}<span><b>${G(l.game).title}</b><small>${l.condition} · ${l.id}</small></span></a></td><td>${player(P(l.player))}</td><td class="right number bid"><a href="?page=lot&lot=${l.id}">${money(l.winning)}</a></td><td>${status(l.status)}</td></tr>`).join('')}</tbody></table>`;}
return head('Экономика аукционов','Деньги зрителей, варианты выбора и результаты назначенных игр','Турнир / Аукционы',btn('lot&lot='+A(D.focusAttempt).lot,'История лота '+icon('arrow'),'quiet'))+`<div class="kpis">${kpi('Объём ставок',money(cohortTotal),`Все варианты ${list.length} аукционов`,'coins')}${kpi('Аукционов',fmt(list.length),'Выбор игры завершён в каждом лоте','game')}${kpi('Средний победивший вариант',list.length?money(Math.round(cohortWinning/list.length)):'—',`Сумма победителей / ${list.length} лотов`,'chart')}${kpi('Рекорд победившего варианта',record?money(record.winning):'—',record?G(record.game).title+' · '+P(record.player).name:'Нет назначений','trophy')}</div><div class="columns"><section><div class="tabs">${playerFilter?`<a href="?page=auctions" class="gold">${P(playerFilter)?.name||'Участник'} ×</a>`:''}<button data-auction-tab="top" class="${state.auctionTab==='top'?'active':''}">Топ лотов</button><button data-auction-tab="players" class="${state.auctionTab==='players'?'active':''}">По участникам</button><button data-auction-tab="unselected" class="${state.auctionTab==='unselected'?'active':''}">Не выпали</button>${state.auctionFilter!=='all'?`<button data-auction-filter="all" class="gold">Сбросить: ${state.auctionFilter} ×</button>`:''}</div><div class="panel"><div class="panel-heading"><h2>${state.auctionTab==='players'?'Экономика назначенных игр':state.auctionTab==='unselected'?'Ставки без назначения':'Самые дорогие победившие варианты'}</h2><span class="small muted">${state.auctionTab==='players'?'Назначенные игры':`В подборке ${pageCount}`}</span></div>${rows}${state.auctionTab==='players'?'':pager('auctions',state.auctionOffset,pageCount)}</div><p class="legend-note" style="margin-top:21px">${state.auctionTab==='unselected'?'Вариант не выбран именно в этом лоте. Эта же игра могла выпасть в другом. Большая сумма сама по себе не означает победу: способ выбора задают правила сезона.':'Общий объём ставок включает все варианты. Победившая сумма относится только к выбранному. Призовой фонд считается отдельно.'}</p></section><aside class="panel panel-inner"><div class="eyebrow">Распределение ставок</div><h2 style="margin-bottom:20px">Бюджеты аукционов</h2>${donut(list)}<p class="legend-note small">Лот относится к жанру выбранной игры. Рубли включают все его варианты.</p></aside></div>`;}
function historyDelta(p){if(p.rank25===null&&p.rank26!==null)return '<span class="muted">Дебют</span>';if(p.rank26===null)return '<span class="muted">Не участвовал</span>';let v=p.rank25-p.rank26;return v>0?`<span class="positive">↑ +${v}</span>`:v<0?`<span class="negative">↓ ${v}</span>`:'<span class="muted">=</span>';}
function historyTable(list=D.history.slice(0,6)){return `<table class="history-table"><thead><tr><th>Участник</th><th class="center">2025</th><th class="center">Лето 2026</th><th class="right">Δ места</th></tr></thead><tbody>${list.map(p=>`<tr><td>${player(P(p.id))}</td><td class="center"><a href="?page=season&season=2025">${p.rank25===null?'—':'#'+p.rank25}</a></td><td class="center"><a href="?page=season&season=2026">${p.rank26===null?'—':'#'+p.rank26}</a></td><td class="right">${historyDelta(p)}</td></tr>`).join('')}</tbody></table>`;}
function hall(){const signature=D.achievements.find(a=>a.rarity==='signature');const podium=D.history.filter(p=>p.rank26&&p.rank26<=3).sort((a,b)=>[2,1,3].indexOf(a.rank26)-[2,1,3].indexOf(b.rank26)).map(p=>[p.id,p.rank26===1?'Чемпион':p.rank26===2?'Серебро':'Бронза',p.rank26===1?'first':p.rank26===2?'silver':'bronze']);return head('Зал славы и архив','Сезоны продолжают историю участников и всего сообщества','История / NASRAL и NASSAL',btn('season','Архив NASSAL 2026 '+icon('arrow'),'quiet'))+`<div class="grid" style="grid-template-columns:1.15fr 1fr;margin-bottom:22px"><section class="panel panel-inner"><div class="spread" style="margin-bottom:20px"><h2>Призёры NASSAL 2026</h2><span class="small muted">Завершённый сезон</span></div><div class="hall-podium">${podium.map(([id,n,c])=>`<a class="champion-card ${c}" href="?page=profile&player=${id}">${avatar(P(id),'')}<span class="pill ${id==='flash'?'gold':''}">${icon('medal','sm')} ${n}</span><b>${P(id).name}</b><small>${'NASSAL 2026 · #'+P(id).rank26}</small></a>`).join('')}</div></section><section class="panel panel-inner"><div class="spread" style="margin-bottom:20px"><h2>Сравнение сезонов</h2><span class="small muted">Места, не сырые GGP</span></div>${historyTable([D.history[0],D.history[1],D.history[2],D.history[3],D.history[4],D.history[10]])}<div class="chart-note" style="padding:14px 0 0">Δ = место в 2025 − место летом 2026. Дебют не считается ростом с нулевого места.</div></section></div><div class="seasons">${[['nasral-2025','','Сезон I'],['nassal-2026','neon','Сезон II'],['nasral-2026','winter','Сезон III']].map(([id,c,label])=>{const e=D.events[id],field=id==='nasral-2025'?'rank25':'rank26',champion=id==='nasral-2026'?null:D.history.find(p=>p[field]===1);return `<a class="season-card ${c}" href="?page=${e.route}"><svg class="season-emblem" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1"><path d="${paths[e.symbol]}"/></svg><div class="section-label">${label}</div><h3>${e.name}</h3><p>${e.theme}</p><div class="season-bottom">${icon(champion?'trophy':'clock','sm')}${champion?'Чемпион: '+champion.name:'Турнир идёт · чемпион не определён'}<span style="margin-left:auto">${icon('arrow','sm')}</span></div></a>`;}).join('')}</div><div class="grid" style="grid-template-columns:1.15fr 1fr;margin-top:22px"><section class="panel panel-inner"><h3>От истоков к современной серии</h3><div class="timeline-horizontal"><div><span class="tiny gold">Общая история</span><strong>Стримхаты → HPG → UPG</strong><small>Ранние форматы и карьеры участников</small></div><div><span class="tiny gold">2024</span><strong>MGE</strong><small>Отдельный ивент, роли игроков и судей</small></div><div><span class="tiny gold">2025–2026</span><strong>NASRAL → NASSAL → NASRAL</strong><small>Титулы современной серии считаются отдельно</small></div></div></section><section class="panel panel-inner signature-showcase"><div class="row" style="gap:20px">${achievementBadge(signature)}<div><h3>${signature.title}</h3><p class="small muted" style="line-height:1.6;margin:12px 0">${P(signature.player).name} · ${signature.criterion}</p>${btn('profile&player='+signature.player,'Карьера чемпиона '+icon('arrow'),'small quiet')}</div></div></section></div>`;}
function awardCard(a){return `<button class="award-card ${a.rarity} ${esc(a.color)}" data-achievement="${a.id}">${awardArt(a)}<span class="award-copy"><span class="rarity-label">${rarityNames[a.rarity]}</span><strong>${a.title}</strong><span class="award-category">${a.category}</span><small>${a.events.map(id=>D.events[id].name).join(' · ')}</small></span></button>`;}
function careerRows(p){const rows=D.careers[p.id]||[];return rows.length?rows.map(c=>{const e=D.events[c.event];return `<div class="career-row"><span class="date">${e.date}</span><div><strong>${e.name}</strong><small>${c.role}</small></div><span class="place">${c.place?'#'+c.place:c.event==='nasral-2026'?'Турнир идёт':c.role==='Судья'?'Судейство':'Участие'}</span></div>`;}).join(''):'<div class="empty-state">Предыдущих выступлений в архиве нет.</div>';}
function profileAwards(p){
 const all=awardsFor(p),list=all.filter(a=>state.awardCategory==='all'||a.category===state.awardCategory),visible=list.slice(state.awardOffset,state.awardOffset+6);
 const featured=D.moments.find(m=>m.player===p.id&&m.featured);
 return `<div class="collection-layout"><section class="panel panel-inner"><div class="spread"><div><div class="eyebrow">Каждый знак — своя история</div><h2>Коллекция достижений</h2></div><span class="small muted">${all.length} регалий</span></div><div class="collection-filters">${['all',...categoryOrder.filter(c=>all.some(a=>a.category===c))].map(c=>`<button data-award-category="${c}" class="${state.awardCategory===c?'active':''}">${c==='all'?'Все':c} <span>${c==='all'?all.length:all.filter(a=>a.category===c).length}</span></button>`).join('')}</div><div class="collection-grid">${visible.map(awardCard).join('')||'<div class="empty-state">Пока нет наград в этой категории.</div>'}</div>${list.length>6?`<div class="pager"><span>${state.awardOffset+1}–${Math.min(state.awardOffset+6,list.length)} из ${list.length}</span><button class="btn small quiet" data-award-page="${state.awardOffset-6}" ${state.awardOffset===0?'disabled':''}>Назад</button><button class="btn small quiet" data-award-page="${state.awardOffset+6}" ${state.awardOffset+6>=list.length?'disabled':''}>Дальше</button></div>`:''}</section><aside class="stack"><section class="panel panel-inner"><div class="eyebrow">Редкость регалий</div><h2>Три вида регалий</h2><div class="rarity-guide">${[['signature','double','Особая регалия','Несколько титулов одной серии.'],['rare','trophy','Редкая','Чемпионство или рекорд.'],['standard','medal','Коллекционная','Призовое место, роль или сезон.']].map(([rarity,symbol,n,t])=>`<div>${awardArt({rarity,symbol,color:''})}<span><b>${n}</b><small>${t}</small></span></div>`).join('')}</div><p class="legend-note">Откройте регалию: условие, ивент и связанный результат. Награды не меняют турнирные очки.</p></section>${featured?`<a class="panel panel-inner moment-preview" href="?page=profile&player=${p.id}&tab=events"><div class="eyebrow">Момент сезона</div><div class="row">${cover(featured.game)}<div><h3>${featured.title}</h3><p>${featured.description}</p></div></div><span class="small gold">Открыть историю ${icon('arrow','sm')}</span></a>`:`<section class="panel panel-inner"><h3>Сезоны и карьера</h3><p class="legend-note">Титулы NASRAL / NASSAL и награды других ивентов сохраняют свой контекст.</p>${btn('profile&player='+p.id+'&tab=history','История участника '+icon('arrow'),'small quiet')}</section>`}</aside></div>`;
}
function profileEvents(p){
 const own=D.moments.filter(m=>m.player===p.id),types={record:'Рекорды',game:'Прохождения',auction:'Аукционы'};
 const filtered=own.filter(m=>(state.eventSeason==='all'||m.event===state.eventSeason)&&(state.eventKind==='all'||m.kind===state.eventKind)&&(state.eventGame==='all'||m.game===state.eventGame)&&(state.eventMedia==='all'||m.media?.type===state.eventMedia)).sort((a,b)=>Number(b.featured)-Number(a.featured)||b.day-a.day);
 const choices=(values,selected)=>values.map(([id,n])=>`<option value="${id}" ${id===selected?'selected':''}>${n}</option>`).join('');
 return `<div class="event-toolbar toolbar"><select id="event-season" class="select" aria-label="Сезон события">${choices([['all','Все сезоны'],...Array.from(new Set(own.map(m=>m.event))).map(id=>[id,D.events[id].name])],state.eventSeason)}</select><select id="event-kind" class="select" aria-label="Тип события">${choices([['all','Все события'],...Object.entries(types)],state.eventKind)}</select><select id="event-game" class="select" aria-label="Игра события">${choices([['all','Все игры'],...Array.from(new Set(own.map(m=>m.game))).map(id=>[id,G(id).title])],state.eventGame)}</select><select id="event-media" class="select" aria-label="Материал">${choices([['all','Все материалы'],['clip','Клипы'],['vod','Полные записи'],['timestamp','Таймкоды']],state.eventMedia)}</select><span class="toolbar-end">Найдено ${filtered.length} событий</span></div><div class="memory-layout"><section class="panel panel-inner"><div class="eyebrow">События участника</div><h2>Памятные события</h2><div class="moment-feed">${filtered.slice(state.eventOffset,state.eventOffset+3).map(m=>`<article class="moment-card" data-moment="${m.id}"><a href="?page=lot&lot=${m.lot}">${cover(m.game,'moment-cover')}</a><div><div class="small muted">${D.events[m.event].name} · День ${m.day} · ${types[m.kind]}</div><h3><a href="?page=lot&lot=${m.lot}">${m.title}</a></h3><p>${m.description}</p><a class="small gold" href="?page=lot&lot=${m.lot}">Варианты, игра и результат ${icon('arrow','sm')}</a></div><span class="media-label">${m.media?'Есть запись':'Без записи'}</span></article>`).join('')||'<div class="empty-state">По этим фильтрам событий нет. Выберите другой тип или материал.</div>'}</div><div class="spread small muted" style="margin-top:16px"><span>Показано ${filtered.length?state.eventOffset+1:0}–${Math.min(state.eventOffset+3,filtered.length)} из ${filtered.length}</span><div class="row"><button class="btn small quiet" data-event-page="${state.eventOffset-3}" ${state.eventOffset===0?'disabled':''}>Назад</button><button class="btn small quiet" data-event-page="${state.eventOffset+3}" ${state.eventOffset+3>=filtered.length?'disabled':''}>Дальше</button><button class="btn small quiet" data-reset-events>Сбросить фильтры</button></div></div></section><aside class="panel panel-inner"><div class="eyebrow">${D.snapshot.season} · ${p.name}</div><h2>История сезона</h2><dl class="stat-list"><div><dt>Событий</dt><dd>${own.length}</dd></div><div><dt>Рекордов</dt><dd>${own.filter(m=>m.kind==='record').length}</dd></div><div><dt>С прикреплённой записью</dt><dd>${own.filter(m=>m.media).length}</dd></div></dl><div class="section-rule"></div><h3>Клипы и записи</h3>${filtered.some(m=>m.media)?filtered.filter(m=>m.media).map(m=>`<a class="btn full quiet" href="${esc(m.media.url)}" target="_blank" rel="noopener noreferrer">${esc(m.title)} ${icon('play','sm')}</a>`).join(''):'<div class="empty-state">'+icon('play','lg')+'Записи не прикреплены. Результаты игр и аукционов сохранены.</div>'}${btn('auctions&player='+p.id,'Аукционы участника '+icon('arrow'),'full quiet')}</aside></div>`;
}
function profile(){
 const p=P(params.get('player')||'mel')||P('mel'),hasCurrent=p.points!==undefined,tab=state.profileTab;
 const current=D.attempts.find(a=>a.player===p.id&&a.status==='playing'),own=D.attempts.filter(a=>a.player===p.id&&a.status==='finished').sort((a,b)=>b.day-a.day||b.id.localeCompare(a.id)).slice(0,4);
 const legacy=Array.from(new Set((D.careers[p.id]||[]).filter(c=>!D.events[c.event].series).map(c=>D.events[c.event].name)));
 const gamesHTML=own.length?own.map(a=>`<a class="profile-game" href="?page=lot&lot=${a.lot}">${cover(a.game)}<div><b>${G(a.game).title}</b><p><span class="positive">+${a.points} GGP</span> · ${duration(a.minutes)}</p></div>${icon('arrow','sm')}</a>`).join(''):'<div class="empty-state">Нет завершённых прохождений этого сезона.</div>';
 const statistics=`<section class="panel panel-inner"><div class="eyebrow">NASRAL 2026 · День 07</div><h2 style="margin-bottom:22px">Статистика сезона</h2>${hasCurrent?`<div class="profile-kpis"><div class="profile-kpi"><span>Пройдено</span><strong class="positive">${p.finished}</strong></div><div class="profile-kpi"><span>Дропы игр</span><strong>${p.dropped}</strong></div><div class="profile-kpi"><span>Игровые часы</span><strong>${fmt(p.minutes/60,1)}</strong></div><div class="profile-kpi"><span>GGP</span><strong class="gold">${fmt(p.points)}</strong></div><div class="profile-kpi wide"><div class="spread"><span>GGP / игровой час</span><strong style="margin:0">${fmt(efficiency(p),1)}</strong></div></div></div>`:'<div class="empty-state">Нет игровых показателей текущего сезона.</div>'}</section>`;
 return head('Профиль участника','Достижения, карьера и моменты, которые помнит комьюнити','Участники / '+esc(p.name),btn('statistics','К участникам '+icon('back'),'quiet'))+`<section class="profile-hero">${imagePortrait(p,'hero-portrait')}<div class="profile-identity"><span class="platform">${p.platform||'Twitch'}</span><h2>${p.name}</h2><p>Карьера в игровых ивентах</p><div class="row">${seasons(p)}${legacy.map(n=>`<span class="season-chip legacy">${n}</span>`).join('')}</div></div><div class="profile-now">${current?`<span class="section-label">Играет сейчас</span><div class="row" style="margin-top:13px">${cover(current.game,'profile-current-cover')}<div><b>${G(current.game).title}</b><p class="small muted">${duration(current.minutes)} · текущая попытка</p></div></div>`:btn('hall','История сезонов '+icon('arrow'),'quiet')}</div></section><div class="tabs">${[['awards','Достижения'],['history','История'],['statistics','Статистика'],['events','События']].map(([id,n])=>`<button data-profile-tab="${id}" class="${tab===id?'active':''}">${n}</button>`).join('')}</div>${tab==='awards'?profileAwards(p):tab==='events'?profileEvents(p):tab==='statistics'?`<div class="profile-stats-layout">${statistics}<section class="panel panel-inner"><div class="eyebrow">Результаты выбранного сезона</div><h2 style="margin-bottom:16px">Последние прохождения</h2>${gamesHTML}</section></div>`:`<div class="profile-columns"><section class="panel panel-inner"><div class="eyebrow">Путь участника</div><h2 style="margin-bottom:20px">Карьера и роли</h2>${careerRows(p)}</section>${statistics}<section class="panel panel-inner"><div class="eyebrow">Игры участника</div><h2 style="margin-bottom:16px">Последние прохождения</h2>${gamesHTML}</section></div>`}<div class="profile-links">${btn('games&player='+p.id,'Игры '+icon('arrow'),'quiet')}${btn('auctions&player='+p.id,'Аукционы '+icon('arrow'),'quiet')}${hasCurrent?btn('comparison&left='+p.id,'Сравнить участника '+icon('arrow'),'quiet'):btn('hall','Сравнить места в архиве '+icon('arrow'),'quiet')}${btn('season','Архив сезонов '+icon('arrow'),'quiet')}</div>`;
}

function comparison(){let requested=params.get('left')||state.compareLeft;let left=active.find(p=>p.id===requested);if(!left){let person=P(requested);return head('Сравнение участников','Нет сопоставимой статистики текущего сезона','Турнир / Статистика / Сравнение',btn('statistics','К статистике '+icon('back'),'quiet'))+`<section class="panel panel-inner"><div class="empty-state"><h2>${person?esc(person.name):'Выбранный участник'}</h2><p>В текущем сезоне нет игровых показателей для сравнения.</p>${btn('hall','Сравнить исторические места '+icon('arrow'),'primary')}</div></section>`;}let right=active.find(p=>p.id===(params.get('right')||state.compareRight))||active[2];if(left.id===right.id)right=active.find(p=>p.id!==left.id);let fields=[['GGP',p=>p.points,0],['Завершённые попытки',p=>p.finished,0],['Дропы игр',p=>p.dropped,0],['Игровые часы',p=>p.minutes/60,1],['GGP / час',p=>efficiency(p),1],['Доля финишей, %',p=>completion(p),1]];return head('Сравнение участников','Один сезон, один период и прозрачные показатели','Турнир / Статистика / Сравнение',btn('statistics','К статистике '+icon('back'),'quiet'))+`<div class="comparison-heroes">${[left,right].map((p,i)=>`<section class="panel comparison-person">${avatar(p)}<div><div class="eyebrow">NASRAL 2026 · День 07</div><h2>${p.name}</h2><p>${p.finished} финишей · ${hours(p.minutes)} · ${fmt(p.points)} GGP</p></div><select id="compare-${i?'right':'left'}" class="select" style="margin-left:auto" aria-label="${i?'Второй':'Первый'} участник">${active.filter(x=>x.id!==(i?left:right).id).map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${x.name}</option>`).join('')}</select></section>`).join('')}</div><section class="panel"><div class="panel-heading"><h2>Показатели текущего сезона</h2><span class="small muted">Без общего «индекса силы»</span></div>${fields.map(([label,get,digits])=>{let max=Math.max(get(left),get(right));return `<div class="compare-row"><span class="label">${label}</span>${[left,right].map((p,i)=>`<div class="compare-value"><strong class="${i?'':'gold'}">${fmt(get(p),digits)}</strong><div class="compare-bar ${i?'blue':''}"><i style="width:${get(p)/max*100}%"></i></div></div>`).join('')}</div>`;}).join('')}</section><div class="grid" style="grid-template-columns:1fr 1fr;margin-top:22px">${[left,right].map(p=>`<section class="panel panel-inner"><div class="spread" style="margin-bottom:20px"><h3>Прохождения ${p.name}</h3><a class="small gold" href="?page=games&player=${p.id}&status=finished">Все игры ${icon('arrow','sm')}</a></div>${library(p.id,5)}</section>`).join('')}</div>`;}
function lot(){let l=L(params.get('lot'))||L(A(D.focusAttempt).lot),a=l.attempt?A(l.attempt):null,p=P(l.player);return head('История игрового назначения','От зрительского выбора до результата прохождения','Аукционы / '+l.id,btn('auctions','К аукционам '+icon('back'),'quiet'))+`<section class="panel lot-hero">${cover(l.game,'cover')}<div><div class="eyebrow">${l.id} · Выбор завершён · День ${l.day}</div><h2>${G(l.game).title}</h2><div class="row"><span class="small muted">${l.condition}</span>${status(l.status)}</div><div style="margin-top:16px">${player(p)}</div></div><div class="hero-end"><div class="small muted">Победивший вариант</div><div class="big-number gold" style="margin:10px 0">${money(l.winning)}</div><div class="small muted">Общий объём аукциона: ${money(l.total)}</div></div></section><div class="lot-chain">${[['coins','Аукцион',money(l.total)],['check','Победивший вариант',money(l.winning)],['game','Назначенная игра',G(l.game).title],['clock','Прохождение',a?duration(a.minutes):'Ожидает старта'],['chart','Результат',a?.points===null?'Не начислены':a?`+${a.points} GGP`:'Нет результата'],['play','Запись',a?.clip?'Доступна':'Не прикреплена']].map(([i,n,v])=>`<div class="chain-node">${icon(i)}<strong>${n}</strong><small>${v}</small></div>`).join('')}</div><div class="grid" style="grid-template-columns:1.1fr 1fr 0.8fr"><section class="panel panel-inner"><div class="eyebrow">Варианты зрительского выбора</div><h2>Состав аукциона</h2>${l.options.map(o=>`<div class="option-row"><div class="game-title">${G(o.game).title}<small>${o.winner?'Выиграл · '+l.condition:'Не выбран · альтернативное назначение'}</small></div><div style="text-align:right"><b class="${o.winner?'gold':''}">${money(o.amount)}</b><small>${fmt(o.amount/l.total*100,1)}% от объёма</small></div></div>`).join('')}<div class="spread" style="margin-top:20px"><span class="small muted">Всего по вариантам</span><b class="number">${money(l.total)}</b></div></section><section class="panel panel-inner"><div class="eyebrow">Конкретная попытка</div><h2>Результат прохождения</h2><dl class="stat-list"><div><dt>Участник</dt><dd style="font-size:20px"><a href="?page=profile&player=${p.id}">${p.name}</a></dd></div><div><dt>Статус игры</dt><dd>${status(l.status)}</dd></div><div><dt>Игровое время</dt><dd>${a?duration(a.minutes):'—'}</dd></div><div><dt>Начисление за попытку</dt><dd class="gold">${a?.points===null?'—':a?fmt(a.points)+' GGP':'—'}</dd></div><div><dt>Сравнение с HLTB</dt><dd class="muted">н/д</dd></div></dl>${btn('standings','Открыть гонку GGP '+icon('arrow'),'full quiet')}</section><section class="panel panel-inner"><div class="eyebrow">Медиа и история</div><h2 style="margin-bottom:23px">Запись события</h2>${a?.clip?`<a class="btn primary recording-link" href="${esc(typeof a.clip==='string'?a.clip:a.clip.url)}" target="_blank" rel="noopener noreferrer">${icon('play')} ${typeof a.clip==='string'?'Открыть запись':a.clip.type==='clip'?'Открыть клип':a.clip.type==='timestamp'?'Смотреть с момента':'Полная запись'}</a>`:`<div class="empty-state">${icon('play','lg')}Запись не прикреплена.<br>${a?'Время, исход и начисление сохранены.':'Назначение сохранено. Прохождение ещё не началось.'}</div>`}<div class="section-rule"></div><h3>Связанные разделы</h3><div class="stack" style="margin-top:20px;gap:12px">${btn('profile&player='+p.id,'Карьера участника '+icon('arrow'),'quiet')}${btn('games&player='+p.id,'Другие попытки '+icon('arrow'),'quiet')}</div></section></div>`;}
function season(){let year=params.get('season')||'2026',is25=year==='2025',title=D.events[is25?'nasral-2025':'nassal-2026'].name,list=D.history.filter(p=>is25?p.rank25!==null:p.rank26!==null).sort((a,b)=>(is25?a.rank25-b.rank25:a.rank26-b.rank26));const champion=list[0],titles=D.careers[champion.id].filter(c=>c.place===1&&D.events[c.event].series);return head('Архив сезона','Итоговые места и карьера участников после завершения ивента','История / '+title,btn('hall','В Зал славы '+icon('back'),'quiet'))+`<section class="archive-intro"><div><div class="eyebrow">${is25?'Сезон I · Fallout':'Сезон II · Vice City'}</div><h2>${title}</h2><p>Сезон завершён · ${list.length} участников · чемпион ${champion.name}</p></div><div class="row">${pill('Итоговые результаты','violet')}<select id="archive-season" class="select" aria-label="Архивный сезон"><option value="2025" ${is25?'selected':''}>NASRAL 2025</option><option value="2026" ${!is25?'selected':''}>NASSAL 2026</option></select></div></section><div class="columns"><section class="panel"><div class="panel-heading"><h2>Финальная турнирная таблица</h2><span class="small muted">${title} · отдельный регламент сезона</span></div><table class="archive-table"><thead><tr><th>Место</th><th>Участник</th><th class="right">Итоговые GGP</th><th class="right">${is25?'Результат':'Изменение с NASRAL 2025'}</th></tr></thead><tbody>${list.map(p=>`<tr><td class="rank-cell">${is25?p.rank25:p.rank26}</td><td>${player(P(p.id))}</td><td class="right number">${is25?'—':fmt(p.points26)}</td><td class="right">${is25?(p.rank25===1?'Чемпион':p.rank25<=3?'Призёр':'Участник'):historyDelta(p)}</td></tr>`).join('')}</tbody></table><div class="chart-note">«—» означает отсутствие данных, а не нулевой результат.</div></section><aside class="stack"><section class="panel panel-inner"><div class="eyebrow">Чемпион сезона</div><div class="row">${avatar(P(champion.id))}<div><h2>${champion.name}</h2><p class="small gold" style="margin:8px 0">I место · ${title}</p></div></div><div class="section-rule"></div><h3>Чемпионства серии</h3><p class="small muted" style="line-height:1.7">${titles.map(c=>D.events[c.event].name).join('<br>')}</p>${btn('profile&player='+champion.id,'Профиль чемпиона '+icon('arrow'),'full quiet')}</section><section class="panel panel-inner"><h3>Хронология начислений</h3><div class="empty-state" style="margin-top:20px">${icon('chart','lg')}История начислений недоступна.<br>Итоговые места сохранены.</div></section><section class="panel panel-inner"><h3>Сравнение сезонов</h3><p class="small muted" style="line-height:1.65">Сопоставляются места. Сырые GGP разных регламентов не складываются в единый рейтинг.</p>${btn('hall','Сравнить места '+icon('arrow'),'full quiet')}</section></aside></div>`;}
function selection(){return candidates()+`<div class="overlay"><section class="drawer" role="dialog" aria-modal="true" aria-label="Проверка состава"><div class="panel-heading"><div><div class="eyebrow">Голосование / Проверка выбора</div><h2>Мой состав</h2></div><a href="?page=candidates" class="btn small quiet" aria-label="Закрыть проверку">${icon('close')}</a></div><div class="drawer-body"><div class="spread" style="margin-bottom:15px"><span class="small muted">Один фаворит + ещё восемь</span>${pill(`${selected.length} / 9 выбрано`,selected.length===9?'green':'orange')}</div>${selected.map(id=>{let p=P(id);return `<div class="selection-person">${avatar(p)}<a href="?page=profile&player=${p.id}"><strong>${p.name}</strong></a><div class="actions"><button class="favorite-btn ${favorite===id?'active':''}" data-favorite="${id}">${icon('star','sm')}${favorite===id?'Фаворит':'Сделать фаворитом'}</button><button class="remove-btn" data-select="${id}" aria-label="Убрать ${p.name}">${icon('close','sm')}</button></div></div>`;}).join('')||'<div class="empty-state">Состав пока пуст. Вернитесь к кандидатам.</div>'}<div class="row" style="margin-top:20px">${icon('info')}<p class="small muted" style="line-height:1.6;margin:0">Фаворит только один. Его можно сменить, не пересобирая весь состав.</p></div></div><div class="drawer-foot"><p>Перед отправкой проверьте состав и правила действующего голосования. Голоса принимаются только на официальном сайте.</p><div class="spread">${btn('candidates','Изменить состав','quiet')}<a class="btn primary" href="https://nasral.pro/vote2026/vote" target="_blank" rel="noopener noreferrer">Открыть голосование ${icon('arrow')}</a></div></div></section></div>`;}
function showAchievement(id){
 const a=D.achievements.find(a=>a.id===id);if(!a)return;
 $('#app').insertAdjacentHTML('beforeend',`<section class="modal achievement-modal" role="dialog" aria-modal="true" aria-label="Подробности регалии"><div class="spread"><span class="eyebrow">${rarityNames[a.rarity]} · ${a.category}</span><button data-close-modal class="btn small quiet" aria-label="Закрыть подробности">${icon('close','sm')}</button></div><div class="award-detail">${awardArt(a)}<div><h2>${a.title}</h2><p>${P(a.player).name} · ${a.events.map(id=>D.events[id].name).join(' / ')}</p></div></div><h3>За что получена</h3><p>${a.criterion}</p><div class="modal-links">${a.links.map(l=>btn(l.route,l.label+' '+icon('arrow'),'quiet')).join('')}${btn('profile&player='+a.player+'&tab=awards','Коллекция '+P(a.player).name,'primary')}</div></section>`);
 $('[data-close-modal]').focus();bindModalLinks();
}
function bindModalLinks(){document.querySelectorAll('.modal a[href^="?page="]').forEach(a=>a.addEventListener('click',e=>{if(e.metaKey||e.ctrlKey||e.shiftKey)return;e.preventDefault();navigate(a.getAttribute('href'));}));}
function showAward(title,customMessage){$('#app').insertAdjacentHTML('beforeend',`<section class="modal" role="dialog" aria-modal="true" aria-label="Выбор состава"><div class="spread"><span class="eyebrow">Выбор состава</span><button data-close-modal class="btn small quiet" aria-label="Закрыть подробности">${icon('close','sm')}</button></div><h2>${esc(title)}</h2><p>${esc(customMessage)}</p></section>`);$('[data-close-modal]').focus();}

function render(){const views={candidates,voting,standings,statistics,games,auctions,hall,profile,comparison,lot,season,selection};if(!views[page])page='candidates';document.title='NASRAL — история, статистика и достижения';$('#app').innerHTML=`<div class="app page-${page}">${header()}<main id="screen">${views[page]()}</main>${footer()}</div>`;bind();history.replaceState({view:{...state}},'',location.href);}
function storeViewState(){if(['candidates','selection'].includes(page))state.candidateSearch=state.search;if(page==='games')state.gameSearch=state.search;}
function restoreViewState(){state.search=page==='games'?(state.gameSearch||''):['candidates','selection'].includes(page)?(state.candidateSearch||''):'';}
function syncURL(){let u=new URL(location.href);u.search=params.toString();history.replaceState({},'',u);}
function navigate(href){storeViewState();let url=new URL(href,location.href);history.pushState({},'',url);params=new URLSearchParams(location.search);page=params.get('page')||'candidates';state.profileTab=params.get('tab')||'awards';state.auctionTab=params.get('auctionTab')||'top';state.gameOffset=5*Math.max(0,Number(params.get('gamePage'))||0);state.auctionOffset=5*Math.max(0,Number(params.get('auctionPage'))||0);state.awardCategory='all';state.awardOffset=0;state.eventSeason=state.eventKind=state.eventGame=state.eventMedia='all';state.eventOffset=0;restoreViewState();render();window.scrollTo(0,0);}
function bind(){
 document.querySelectorAll('[data-list]').forEach(b=>b.addEventListener('click',()=>{let games=b.dataset.list==='games',key=games?'gameOffset':'auctionOffset',param=games?'gamePage':'auctionPage';state[key]=Number(b.dataset.offset);params.set(param,String(state[key]/5));syncURL();render();}));

 document.querySelectorAll('[data-event-page]').forEach(b=>b.addEventListener('click',()=>{state.eventOffset=Number(b.dataset.eventPage);render();}));
 document.querySelectorAll('[data-achievement]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();showAchievement(b.dataset.achievement);}));
 document.querySelectorAll('[data-award-category]').forEach(b=>b.addEventListener('click',()=>{state.awardCategory=b.dataset.awardCategory;state.awardOffset=0;render();}));
 document.querySelectorAll('[data-award-page]').forEach(b=>b.addEventListener('click',()=>{state.awardOffset=Number(b.dataset.awardPage);render();}));
 document.querySelectorAll('[data-reset-events]').forEach(b=>b.addEventListener('click',()=>{state.eventSeason=state.eventKind=state.eventGame=state.eventMedia='all';state.eventOffset=0;render();}));
document.querySelectorAll('a[href^="?page="]').forEach(a=>a.addEventListener('click',e=>{if(e.metaKey||e.ctrlKey||e.shiftKey)return;e.preventDefault();navigate(a.getAttribute('href'));}));document.querySelectorAll('[data-select]').forEach(b=>b.addEventListener('click',()=>{let id=b.dataset.select;if(selected.includes(id)){selected=selected.filter(x=>x!==id);if(favorite===id)favorite=selected[0]||null;}else if(selected.length<9){selected.push(id);if(!favorite)favorite=id;}else{showAward('В составе уже девять кандидатов','Уберите одного участника перед добавлением нового. Лимит текущего состава — девять различных кандидатов.');return;}saveSelection();render();}));document.querySelectorAll('[data-favorite]').forEach(b=>b.addEventListener('click',()=>{favorite=b.dataset.favorite;saveSelection();render();}));document.querySelectorAll('[data-candidate-page]').forEach(b=>b.addEventListener('click',()=>{state.candidateOffset=Number(b.dataset.candidatePage);render();}));document.querySelectorAll('[data-award]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();showAward(b.dataset.award,'Подробности доступны в коллекции участника.');}));document.querySelectorAll('[data-close-modal]').forEach(b=>b.addEventListener('click',()=>$('.modal')?.remove()));document.querySelectorAll('[data-search]').forEach(input=>input.addEventListener('input',()=>{let start=input.selectionStart,id=input.id;state.search=input.value;state.candidateOffset=0;if(page==='games'){state.gameOffset=0;params.delete('gamePage');syncURL();}render();let fresh=document.getElementById(id);fresh.focus();fresh.setSelectionRange(start,start);}));const change=(id,fn)=>{let e=document.getElementById(id);if(e)e.addEventListener('change',()=>{fn(e.value);render();});};for(const [id,key] of [['event-season','eventSeason'],['event-kind','eventKind'],['event-game','eventGame'],['event-media','eventMedia']])change(id,v=>{state[key]=v;state.eventOffset=0;});change('platform-select',v=>{state.platform=v;state.candidateOffset=0;});change('game-player',v=>{state.gamePlayer=v;state.gameOffset=0;params.delete('gamePage');params.set('player',v);syncURL();});change('game-status',v=>{state.gameStatus=v;state.gameOffset=0;params.delete('gamePage');params.set('status',v);syncURL();});change('donut-mode',v=>{state.donutMode=v;state.auctionFilter='all';state.auctionOffset=0;params.delete('auctionPage');syncURL();});change('donut-unit',v=>state.donutUnit=v);change('compare-left',v=>{state.compareLeft=v;params.set('left',v);syncURL();});change('compare-right',v=>{state.compareRight=v;params.set('right',v);syncURL();});change('archive-season',v=>navigate('?page=season&season='+v));document.querySelectorAll('[data-sort]').forEach(b=>b.addEventListener('click',()=>{let f=b.dataset.sort;state.statsDirection=state.statsSort===f?-state.statsDirection:-1;state.statsSort=f;render();}));for(let [attr,key] of [['data-stats-tab','statsTab'],['data-vote-tab','voteTab'],['data-profile-tab','profileTab'],['data-auction-tab','auctionTab'],['data-auction-filter','auctionFilter']])document.querySelectorAll(`[${attr}]`).forEach(b=>b.addEventListener('click',()=>{state[key]=b.getAttribute(attr);if(attr==='data-stats-tab'){state.statsSort=state.statsTab==='efficiency'?'efficiency':'points';state.statsDirection=-1;}if(attr==='data-auction-tab'||attr==='data-auction-filter'){state.auctionOffset=0;params.delete('auctionPage');syncURL();}if(attr==='data-profile-tab'){params.set('tab',state[key]);syncURL();}if(attr==='data-auction-tab'){params.set('auctionTab',state[key]);syncURL();}render();}));}
document.addEventListener('click',e=>{if(e.target.closest('[data-close-modal]'))$('.modal')?.remove();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('.modal')?.remove();});
window.addEventListener('popstate',e=>{params=new URLSearchParams(location.search);page=params.get('page')||'candidates';if(e.state?.view)state={...state,...e.state.view};else{state.profileTab=params.get('tab')||'awards';state.auctionTab=params.get('auctionTab')||'top';restoreViewState();}render();});
window.NASRAL_APP={metrics,render,getState:()=>({page,selected:[...selected],favorite,...state})};
render();
